Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  // Group transactions by coin name for aggregated calculations
  final groupedTransactions = transactions.groupBy((txn) => txn.coinName);

  // Calculate average profit/loss per coin
  final avgProfitsAndLosses = <String, double>{};
  groupedTransactions.forEach((coin, coinTransactions) {
    double totalProfitLoss = 0;
    for (var txn in coinTransactions) {
      totalProfitLoss += txn.profitLoss;
    }
    avgProfitsAndLosses[coin] = totalProfitLoss / coinTransactions.length;
  });

  return avgProfitsAndLosses;
}

