function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives: (Helper - could be refined with NLP for accuracy)
  for (let i = 0; i < words.length; i++) {
    if (['adjective', 'adverb'].includes(posTag(words[i]))) {  // Simplified POS tagging, enhance with a library for better results
      adjectiveIndices.push(i);
    }
  }

  // 2. Swap if Multiple Adjectives Exist:
  if (adjectiveIndices.length >= 2) {
    const [firstIndex, secondIndex] = adjectiveIndices.slice(0, 2);  
    [words[firstIndex], words[secondIndex]] = [words[secondIndex], words[firstIndex]]; 
  }

  // 3. Reconstruct & Return:
  return words.join(' ');
}

// Example Usage (POS tagging placeholder - integrate a real library like 'compromise' for accuracy)
function posTag(word) {  // Simulated, replace with robust NLP library call
  return word.match(/adjective|adverb/) ? 'adjective' : 'noun'; // Simplified for demo
}

const sentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectives(sentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park
