pair<int, int> fibonacci(int prev1, int prev2, int count, bool& isValid) {
    if (count <= 0) {  // Base case: Generate nothing if count is invalid
        isValid = false;
        return make_pair(prev1, prev2); // Return original values
    } else if (count == 1) {  // Base case: Single element sequence
