#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Include for JSON handling (rapidjson is another excellent choice)

using json = nlohmann::json;
using namespace std;

// In-place Bubble Sort with optimization for already sorted sections
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped;
    do {
        swapped = false;
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i + 1]) {
                swap(arr[i], arr[i + 1]);
                swapped = true;
            }
        }
        // If no swaps occurred, the array is sorted
        if (!swapped) break;
    } while (true);
}

int main() {
    // **JSON Data Handling (Example with Input)**
    string jsonData = R"({ "array": [5, 2, 9, 1, 5, 6] })";
    json j = json::parse(jsonData);
    vector<int> numbers = j["array"]; // Extract integers into a vector

