import UIKit // For indirect Excel interaction (library like SwiftXL would be ideal for direct Excel manipulation in a robust production setting)
import Foundation

func generateSkiSnowComparison(sportPreference: String) -> String { // Returns formatted Excel-table like string

    var comparisonTable = """
    ## Skiing vs. Snowboarding Analysis (Tailored to \(sportPreference))

    | Factor         | Skiing                  | Snowboarding               |
    |----------------|--------------------------|---------------------------|
    | **Speed**      | High (Emphasis on carving) | Moderate to High (Carving & freeriding variations) |
    | **Difficulty** | Beginner-friendly initially, advanced techniques demanding | Steeper initial learning curve, but accessible progression  |
    | **Style**      | Classic, elegant, directional | More freestyle, edgy, versatile |
    | **Learning Curve** | Relatively quicker basics, mastery takes time | Initially steeper, but intuitive progression once grasped |
    | **Terrain Variety** | Excellent across groomed runs, backcountry, parks  | Thrives in parks, powder, varied terrain, adaptable |
    | **Trick Opportunities** | Limited to mogul jumps, park features (developing) | Extensive in parks, freeriding tricks abundant |
    """

    // Conditional Enhancements (Emphasize based on preference)
    if sportPreference.lowercased() == "skiing" {
        comparisonTable = comparisonTable.replacingOccurrences(of: "**Speed**", with: "**Speed**  * (Strong Suit)")
        comparisonTable = comparisonTable.replacingOccurrences(of: "**Terrain Variety**", with: "**Terrain Variety** * (Highly Versatile)")
    } else if sportPreference.lowercased() == "snowboarding" {
        comparisonTable = comparisonTable.replacingOccurrences(of: "**Style**", with: "**Style** * (Distinctive Emphasis)")
        comparisonTable = comparisonTable.replacingOccurrences(of: "**Trick Opportunities**", with: "**Trick Opportunities** * (Wide Range)")
    }

    return comparisonTable
}

